83	    };
84	    const onChanged = (changes: Record<string, { newValue?: unknown }>, areaName: string) => {
85	      if (areaName === "session" && SESSION_KEYS.sidepanelView in changes) take(changes[SESSION_KEYS.sidepanelView]!.newValue);
86	    };
87	    browser.storage.onChanged.addListener(onChanged);
88	    void browser.windows
89	      .getCurrent()
90	      .then((w) => (windowId = w.id))
91	      .catch(() => undefined)
92	      .then(() => browser.storage.session.get(SESSION_KEYS.sidepanelView))
93	      .then((r) => take(r[SESSION_KEYS.sidepanelView]));
94	    return () => browser.storage.onChanged.removeListener(onChanged);
95	  }, []);
96	
97	  return (
98	    <div className="flex h-screen flex-col bg-ink-900">
99	      <header className="flex items-center justify-between border-b border-ink-800 px-4 py-3">
100	        <Wordmark />
101	        <StatusBadge status={t.status} labels={ui.status} />
102	      </header>
103	
104	      <section className="space-y-2 border-b border-ink-800 px-4 py-3">
105	        <div className="flex items-center gap-3">
106	          <div className="min-w-0 flex-1">
107	            {capturing ? (
108	              <>
109	                <p className="text-[11px] font-medium tracking-wide text-ink-500 uppercase">{here ? m.panel.capturingHere : m.panel.capturingOther}</p>
110	                <p className="truncate text-sm text-ink-100" title={snap.tabTitle ?? undefined}>
111	                  {snap.tabTitle || m.common.untitledTab}
112	                </p>
113	              </>
114	            ) : (
115	              <>
116	                <p className="text-[11px] font-medium tracking-wide text-ink-500 uppercase">{m.panel.currentTab}</p>
117	                <p className="truncate text-sm text-ink-100" title={tab?.title}>
118	                  {tab?.title || m.common.thisTab}
119	                </p>
120	              </>
121	            )}
122	          </div>
123	          {capturing ? (
124	            <button
125	              type="button"
126	              onClick={() => void cmd.stop()}
127	              disabled={cmd.pending}
128	              className="inline-flex h-9 shrink-0 items-center gap-1.5 rounded-lg bg-live px-3.5 text-sm font-semibold text-white hover:brightness-110 disabled:opacity-50"
129	            >
130	              <StopIcon size={14} /> {m.panel.stop}
131	            </button>
132	          ) : (
133	            <button
134	              type="button"
135	              onClick={() => tab?.id && void cmd.start(tab.id)}
136	              disabled={!tab?.id || Boolean(restricted) || cmd.pending}
137	              className="inline-flex h-9 shrink-0 items-center gap-1.5 rounded-lg bg-accent px-3.5 text-sm font-semibold text-accent-ink hover:bg-accent-strong disabled:opacity-40"
138	            >
139	              <PlayIcon size={14} /> {cmd.pending ? m.panel.starting : m.panel.start}
140	            </button>
141	          )}
142	        </div>
143	        {capturing && !here && tab?.id && !restricted && (
144	          <button type="button" onClick={() => void cmd.start(tab.id!)} className="text-xs text-accent hover:underline" disabled={cmd.pending}>
145	            {m.panel.switchTab}
146	          </button>
147	        )}
148	        {restricted && !capturing && <p className="text-xs text-accent">{m.errors[restricted]}</p>}
149	        {capturing && snap.overlayHidden && (
150	          <button type="button" onClick={() => void cmd.showOverlay()} className="block text-xs text-accent hover:underline">
151	            {m.panel.showOverlay}
152	          </button>
153	        )}
154	        {missingKey && !capturing && !error && (
155	          <div data-testid="needs-key" className="rounded-lg bg-ink-850 px-3 py-2.5 text-xs leading-relaxed text-ink-200 ring-1 ring-ink-700">
156	            <p>
157	              <span className="font-semibold text-ink-100">{m.common.addKeyTitle}</span>{" "}
158	              {server.status === "no_server_key" ? m.panel.noServerKey(serverUrl ?? "") : m.panel.noServer(serverUrl ?? "")}
159	            </p>
160	            <button type="button" onClick={goToKey} className="mt-1.5 font-semibold text-accent hover:underline">
161	              {m.common.addKeyLink}
162	            </button>
163	          </div>
164	        )}
165	        {error && (
166	          <div role="alert" className="rounded-lg bg-live/10 px-3 py-2 text-xs leading-relaxed text-live ring-1 ring-live/25">
167	            <p>{error}</p>
168	            {keyAction && (
169	              <button type="button" onClick={goToKey} className="mt-1.5 font-semibold underline hover:no-underline">
170	                {userKey.hasKey ? m.common.checkKey : m.common.addDeepgramKey}
171	              </button>
172	            )}
173	          </div>
174	        )}
175	        {warning && !error && <p className="text-xs text-accent">{warning}</p>}
176	      </section>
177	
178	      <nav className="flex gap-1 px-4 pt-3" aria-label={m.panel.sections}>
179	        {(
180	          [
181	            ["transcript", m.panel.transcriptTab],
182	            ["settings", m.panel.settingsTab],
183	          ] as const
184	        ).map(([v, label]) => (
185	          <button
186	            key={v}
187	            type="button"
188	            onClick={() => setView(v)}
189	            aria-current={view === v ? "page" : undefined}
190	            className={`h-8 rounded-lg px-3 text-sm font-medium transition-colors ${
191	              view === v ? "bg-ink-800 text-ink-100" : "text-ink-400 hover:text-ink-100"
192	            }`}
193	          >
194	            {label}
195	          </button>
196	        ))}
197	      </nav>
198	
199	      {view === "transcript" ? (
200	        <main className="flex min-h-0 flex-1 flex-col">
201	          <TranscriptToolbar
202	            className="px-4 py-3"
203	            lines={t.lines}
204	            query={query}
205	            onQueryChange={setQuery}
206	            fileName={snap.tabTitle ? m.panel.fileName(snap.tabTitle) : "heard-transcript"}
207	            labels={ui.toolbar}
208	          />
209	          <TranscriptView
210	            lines={t.lines}
211	            caption={t.caption}
212	            live={capturing}
213	            query={query}
214	            timeBase="stream"
215	            emptyState={capturing ? m.panel.emptyLive : m.panel.emptyIdle}
216	            labels={ui.transcript}
217	            translations={t.translation?.target ? t.translation.lines : undefined}
218	            captionTranslation={t.translation?.target ? t.translation.caption : null}
219	          />
220	          <TranslationNotice issue={t.translation?.target ? t.translation.issue : null} className="border-t border-ink-800 px-4 py-2.5" labels={ui.language} />
221	        </main>
222	      ) : (
223	        <main className="heard-scroll min-h-0 flex-1 space-y-6 overflow-y-auto px-4 py-4">
224	          <KeySection
225	            masked={userKey.masked}
226	            serverUrl={serverUrl}
227	            serverStatus={server.status}
228	            onRecheck={server.recheck}
229	            capturing={capturing}
230	            focusSignal={focusKey}
231	            t={m}
232	          />
233	          <SettingsSection t={m} ui={ui} />
234	          <InterfaceLanguageSection t={m} setting={i18n.setting} auto={i18n.auto} onChange={i18n.setLanguage} />
235	          <ServerUrlSection usingUserKey={userKey.hasKey} t={m} />
236	        </main>
237	      )}
238	
239	      <footer className="border-t border-ink-800 px-4 py-2.5 text-[11px] leading-relaxed text-ink-500">
240	        {m.common.privacy}
241	      </footer>
242	    </div>
243	  );
244	}
245	
246	function SettingsSection({ t, ui }: { t: ExtensionMessages; ui: SharedUiLabels }) {
247	  const [settings, setSettings] = useCaptionSettings();
248	  if (!settings) return null;
249	  return (
250	    <section>
251	      <h2 className="mb-3 text-sm font-semibold text-ink-100">{t.style.title}</h2>
252	      <CaptionSettingsForm settings={settings} onChange={setSettings} showPosition={false} labels={{ ...ui.settings, language: ui.language }} />
253	      <p className="mt-3 text-xs text-ink-500">{t.style.note}</p>
254	    </section>
255	  );
256	}
257	
258	function InterfaceLanguageSection({
259	  t,
260	  setting,
261	  auto,
262	  onChange,
263	}: {
264	  t: ExtensionMessages;
265	  setting: Locale | "" | null;
266	  auto: Locale;
267	  onChange: (value: Locale | "") => void;
268	}) {
269	  if (setting === null) return null;
270	  return (
271	    <section>
272	      <h2 className="mb-1 text-sm font-semibold text-ink-100">
273	        <label htmlFor="ui-language">{t.interface.title}</label>
274	      </h2>
275	      <p className="mb-3 text-xs leading-relaxed text-ink-400">{t.interface.note}</p>
276	      <select
277	        id="ui-language"
278	        value={setting}
279	        onChange={(e) => onChange(isLocale(e.target.value) ? e.target.value : "")}
280	        className="h-9 w-full rounded-lg bg-ink-850 px-2.5 text-sm text-ink-100 ring-1 ring-ink-700 focus:ring-accent focus:outline-none"
281	      >
282	        <option value="">{t.interface.auto(LOCALE_NAMES[auto])}</option>
283	        {LOCALES.map((l) => (
284	          <option key={l} value={l} lang={l}>
285	            {LOCALE_NAMES[l]}
286	          </option>
287	        ))}
288	      </select>
289	    </section>
290	  );
291	}
292	
293	function KeySection({
294	  masked,
295	  serverUrl,
296	  serverStatus,
297	  onRecheck,
298	  capturing,
299	  focusSignal,
300	  t,
301	}: {
302	  t: ExtensionMessages;
303	  masked: string | null;
304	  serverUrl: string | null;
305	  serverStatus: ServerStatus | "checking" | null;
306	  onRecheck: () => void;
307	  capturing: boolean;
308	  focusSignal: number;
309	}) {
310	  const [value, setValue] = useState("");
311	  const [reveal, setReveal] = useState(false);
312	  const [busy, setBusy] = useState(false);
313	  const [message, setMessage] = useState<{ ok: boolean; text: string } | null>(null);
314	  const inputRef = useRef<HTMLInputElement>(null);
315	  const sectionRef = useRef<HTMLElement>(null);
316	
317	  useEffect(() => {
318	    if (focusSignal === 0) return;
319	    sectionRef.current?.scrollIntoView({ block: "start" });
320	    inputRef.current?.focus();
321	  }, [focusSignal]);
322	
323	  const save = async (e: FormEvent) => {
324	    e.preventDefault();
325	    const key = value.trim();
326	    if (!key) {
327	      setMessage({ ok: false, text: t.key.empty });
328	      return;
329	    }
330	    if (!looksLikeDeepgramKey(key)) {
331	      setMessage({ ok: false, text: t.key.malformed });
332	      return;
333	    }
334	    setBusy(true);
335	    setMessage(null);
336	    const result = await verifyDeepgramKey(key);
337	    setBusy(false);
338	    if (result === "rejected") {
339	      setMessage({ ok: false, text: t.key.rejected });
340	      return;
341	    }
342	    if (result === "offline") {
343	      setMessage({ ok: false, text: t.key.offline });
344	      return;
345	    }
346	    await browser.storage.local.set({ [STORAGE_KEYS.deepgramKey]: key });
347	    setValue("");
348	    setReveal(false);
349	    setMessage({ ok: true, text: capturing ? t.key.savedNext : t.key.saved });
350	  };
351	
352	  const forget = async () => {
353	    await browser.storage.local.remove(STORAGE_KEYS.deepgramKey);
354	    setMessage({ ok: true, text: t.key.removed });
355	    onRecheck();
356	  };
357	
358	  const status = (() => {
359	    if (masked) return t.key.using(masked);
360	    const where = serverUrl ?? DEFAULT_HEARD_URL;
361	    if (serverStatus === "unreachable") return t.key.unreachable(where);
362	    if (serverStatus === "no_server_key") return t.key.noServerKey(where);
363	    if (serverStatus === "checking") return t.key.checking(where);
364	    return t.key.usingServer(where);
365	  })();
366	  const statusOk = Boolean(masked) || serverStatus === "ready" || serverStatus === "unknown";
367	
368	  return (
369	    <section ref={sectionRef} aria-labelledby="key-heading">
370	      <h2 id="key-heading" className="mb-1 text-sm font-semibold text-ink-100">
371	        {t.key.title}
372	      </h2>
373	      <p data-testid="key-status" className={`mb-2 text-xs font-medium ${statusOk ? "text-ok" : "text-accent"}`}>
374	        {status}
375	      </p>
376	      <p className="mb-3 text-xs leading-relaxed text-ink-400">
377	        {t.key.introBefore}
378	        <a href={DEEPGRAM_CONSOLE_URL} target="_blank" rel="noreferrer" className="text-accent hover:underline">
379	          console.deepgram.com
380	        </a>
381	        {t.key.introAfter}
382	      </p>
383	      <form onSubmit={save} className="space-y-2">
384	        <label className="sr-only" htmlFor="deepgram-key">
385	          {t.key.label}
386	        </label>
387	        <div className="flex gap-2">
388	          <input
389	            ref={inputRef}
390	            id="deepgram-key"
391	            type={reveal ? "text" : "password"}
392	            value={value}
393	            onChange={(e) => {
394	              setValue(e.target.value);
395	              setMessage(null);
396	            }}
397	            placeholder={masked ? t.key.placeholderReplace : t.key.placeholder}
398	            autoComplete="off"
399	            spellCheck={false}
400	            className="h-9 min-w-0 flex-1 rounded-lg bg-ink-850 px-3 font-mono text-xs text-ink-100 ring-1 ring-ink-700 placeholder:font-sans placeholder:text-ink-500 focus:ring-accent focus:outline-none"
401	          />
402	          <button
403	            type="button"
404	            onClick={() => setReveal((r) => !r)}
405	            aria-pressed={reveal}
406	            aria-controls="deepgram-key"
407	            className="h-9 shrink-0 rounded-lg px-2.5 text-xs text-ink-300 ring-1 ring-ink-700 hover:bg-ink-800 hover:text-ink-100"
408	          >
409	            {reveal ? t.key.hide : t.key.show}
410	          </button>
411	        </div>
412	        <div className="flex items-center gap-3">
413	          <button
414	            type="submit"
415	            disabled={busy}
416	            className="h-9 rounded-lg bg-accent px-3 text-sm font-semibold text-accent-ink hover:bg-accent-strong disabled:opacity-50"
417	          >
418	            {busy ? t.key.verifying : t.key.save}
419	          </button>
420	          {masked && (
421	            <button type="button" onClick={() => void forget()} className="text-xs text-ink-400 hover:text-ink-100 hover:underline">
422	              {t.key.forget}
423	            </button>
424	          )}
425	        </div>
426	      </form>
427	      {message && (
428	        <p role={message.ok ? "status" : "alert"} data-testid="key-message" className={`mt-2 text-xs leading-relaxed ${message.ok ? "text-ok" : "text-live"}`}>
429	          {message.text}
430	        </p>
431	      )}
432	      <p className="mt-2 text-[11px] leading-relaxed text-ink-500">
433	        {t.key.privacy}
434	      </p>
435	    </section>
436	  );
437	}
438	
439	function ServerUrlSection({ usingUserKey, t }: { usingUserKey: boolean; t: ExtensionMessages }) {
440	  const current = useServerUrl();
441	  const [value, setValue] = useState("");
442	  const [message, setMessage] = useState<{ ok: boolean; text: string } | null>(null);
443	
444	  useEffect(() => {
445	    if (current) setValue(current);
446	  }, [current]);
447	
448	  const save = async (e: FormEvent) => {
449	    e.preventDefault();
450	    const normalized = normalizeServerUrl(value);
451	    if (!normalized) {
452	      setMessage({ ok: false, text: t.server.invalid });
453	      return;
454	    }
455	    await browser.storage.local.set({ [STORAGE_KEYS.serverUrl]: normalized });
456	    setMessage({ ok: true, text: t.server.saved });
457	  };
458	
459	  const reset = async () => {
460	    await browser.storage.local.remove(STORAGE_KEYS.serverUrl);
461	    setMessage({ ok: true, text: t.server.resetDone });
462	  };
463	
464	  return (
465	    <section>
466	      <h2 className="mb-1 text-sm font-semibold text-ink-100">{t.server.title}</h2>
467	      <p className="mb-3 text-xs leading-relaxed text-ink-400">
468	        {usingUserKey ? t.server.unused : t.server.about}
469	      </p>
470	      <form onSubmit={save} className="flex gap-2">
471	        <label className="sr-only" htmlFor="server-url">
472	          {t.server.label}
473	        </label>
474	        <input
475	          id="server-url"
476	          type="url"
477	          value={value}
478	          onChange={(e) => {
479	            setValue(e.target.value);
480	            setMessage(null);
481	          }}
482	          placeholder={DEFAULT_HEARD_URL}
483	          spellCheck={false}
484	          className="h-9 min-w-0 flex-1 rounded-lg bg-ink-850 px-3 font-mono text-xs text-ink-100 ring-1 ring-ink-700 placeholder:text-ink-500 focus:ring-accent focus:outline-none"
485	        />
486	        <button type="submit" className="h-9 rounded-lg bg-ink-700 px-3 text-sm font-medium text-ink-100 hover:bg-ink-600">
487	          {t.server.save}
488	        </button>
489	      </form>
490	      <div className="mt-2 flex items-center justify-between gap-2 text-xs">
491	        <span className={message ? (message.ok ? "text-ok" : "text-live") : "text-ink-500"}>{message?.text ?? t.server.defaultIs(DEFAULT_HEARD_URL)}</span>
492	        {current !== DEFAULT_HEARD_URL && (
493	          <button type="button" onClick={() => void reset()} className="shrink-0 text-ink-400 hover:text-ink-100 hover:underline">
494	            {t.server.reset}
495	          </button>
496	        )}
497	      </div>
498	    </section>
499	  );
500	}
